"Bu faturayı stoktan düş (eşleşen malzemelerden çıkış)": "خصم هذه الفاتورة من المخزون (إخراج من المواد المطابقة)",
"Bu görev tanımını okudum, anladım; görevimle ilgili İSG eğitimlerini aldım ve belirtilen kurallara uyacağımı taahhüt ederim. Bir nüshası tarafıma teslim edilmiştir.": "قرأت تعريف المهمة هذا وفهمته؛ وتلقيت تدريبات السلامة المهنية المتعلقة بمهمتي وأتعهّد بالالتزام بالقواعد المذكورة. وقد سُلّمت لي نسخة منه.",
"Bu güncelleme küçük iyileştirmeler ve düzeltmeler içeriyor. Son sürümün notları:": "يتضمن هذا التحديث تحسينات وإصلاحات صغيرة. ملاحظات الإصدار الأخير:",
"Bu kişi daha önce tanımlanan bir yüze benzediği için otomatik önerildi; doğru değilse değiştirin.": "اقتُرح هذا الشخص تلقائيًا لأنه يشبه وجهًا معرّفًا سابقًا؛ غيّره إذا لم يكن صحيحًا.",
"Bu kurallar tüm kullanıcılara uygulanır: şifre değiştirme, giriş, oturum süresi, kaba kuvvet kilidi ve PIN.": "تُطبَّق هذه القواعد على جميع المستخدمين: تغيير كلمة المرور، الدخول، مدة الجلسة، قفل القوة الغاشمة، ورمز PIN.",
"Bu modül yalnızca sistem sahibine açıktır.": "هذه الوحدة متاحة لمالك النظام فقط.",
"Bu personelde yüklü İş Başvuru Formu yok; bilgileri elle girebilirsiniz.": "لا يوجد نموذج طلب توظيف مرفوع لهذا الموظف؛ يمكنك إدخال المعلومات يدوياً.",
"Bu satıra özel açıklama (ör. marka, ölçü, aciliyet)": "وصف خاص بهذا السطر (مثل العلامة التجارية، القياس، الاستعجال)",
